async def execute(call_id):
    """Fetch the call context."""
    return env['ai.coworker'].pbx_call_get(int(call_id))

async def execute(call_id, queue_id):
    """Transfer to a queue."""
    return env['ai.coworker'].pbx_transfer_queue(int(call_id), int(queue_id))

async def execute(call_id, extension_id):
    """Forward to extension."""
    return env['ai.coworker'].pbx_transfer_extension(int(call_id), int(extension_id))
